{
  "selections": [
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '괜찮지 않은 모습'을 감추고 있다고 말하며, 힘들거나 서운한 감정을 드러내는 것이 수치스러운 일이라는 느낌을 표현함. 결함/수치심 도식과, 부모가 힘들어하는 모습을 감추도록 요구한 성장 경험이 직접 연결됨."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 '감추고 있는 걸 눈치챈 거 아닌가, 결국 떠날 것 같다'고 직접 표현함. 연인이 '무슨 생각을 하는지 모르겠다'고 한 상황에서 '진짜 나를 알면 떠날 것'이라는 핵심 신념이 활성화됨."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 힘들다는 감정을 인식하는 순간 '이걸 말해야 하나'라는 생각이 따라와서 또 누른다고 설명함. 진짜 감정을 들키는 것이 끔찍한 일이라는 태도가 '말해야 하나'라는 자동적 생각으로 나타남."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '평소에는 안 하던 말을 하는 느낌'이라고 표현하며, 괜찮은 모습만 유지해야 하고 약한 모습을 드러내면 안 된다는 규칙이 작동하고 있음을 보여줌. '말해야 하나'라는 생각이 이 규칙의 단속 기능으로 작용함."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 힘들다는 말을 하려는 순간 '결국 떠날 것 같다'는 느낌이 따라온다고 표현함. 힘든 모습을 보이면 실망해서 떠날 것이라는 부정적 가정과, 연인의 서운함 표현이 같은 구조를 공유함."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '말하지 않고 혼자 삼킨다'고 직접 진술하며, 힘든 감정을 누구에게도 털어놓지 않고 혼자 삭이는 대처 전략이 상담 장면에서 그대로 관찰됨. 삼키려는 느낌과 명치 조임이 이 전략의 신체적 표현임."
    }
  ]
}

